<script setup>
import { computed,nextTick,onBeforeUnmount,onMounted,ref } from 'vue'
import { useRoute } from 'vue-router'
import { Button,Empty,Input } from 'ant-design-vue'
import { useDocumentRead } from './documentState.js'
import ReadState from './ReadState.vue'
import { remembered,useBrowseMemory } from './browseMemory.js'
import Facts from './Facts.vue'
const route=useRoute(),props=defineProps({documentId:String,memory:{type:Object,default:()=>({})}});const emit=defineEmits(['locate'])
const snapshot=useDocumentRead('snapshot'),nodes=useDocumentRead('nodes'),detail=useDocumentRead('node'),incoming=useDocumentRead('relations'),outgoing=useDocumentRead('relations'),table=useDocumentRead('table'),graph=useDocumentRead('graph'),children=useDocumentRead('nodes'),evidence=useDocumentRead('nodes'),community=useDocumentRead('nodes')
const mode=remembered(props.memory,'mode','STRUCTURE_NODE'),keyword=remembered(props.memory,'keyword',''),appliedKeyword=remembered(props.memory,'appliedKeyword',''),entityType=remembered(props.memory,'entityType',''),level=remembered(props.memory,'level',''),page=remembered(props.memory,'page',1),selected=remembered(props.memory,'selected',null),trail=remembered(props.memory,'trail',[]),incomingPage=remembered(props.memory,'incomingPage',1),outgoingPage=remembered(props.memory,'outgoingPage',1),rowPage=remembered(props.memory,'rowPage',1),columnOffset=remembered(props.memory,'columnOffset',0),childPage=remembered(props.memory,'childPage',1),graphLimit=remembered(props.memory,'graphLimit','80'),graphView=remembered(props.memory,'graphView',false),zoom=remembered(props.memory,'zoom',1),evidencePage=remembered(props.memory,'evidencePage',1),communityPage=remembered(props.memory,'communityPage',1)
let alive=true,navigationEpoch=0
onBeforeUnmount(()=>{alive=false})
const restoreScroll=useBrowseMemory(props.memory,{mode,keyword,appliedKeyword,entityType,level,page,selected,trail,incomingPage,outgoingPage,rowPage,columnOffset,childPage,graphLimit,graphView,zoom,evidencePage,communityPage})
const modes=[['STRUCTURE_NODE','文档结构'],['PARSE_BLOCK','解析块'],['PARENT_BLOCK','父块'],['CHILD_CHUNK','子块'],['TABLE','表格'],['KG_ENTITY','图谱实体'],['KG_COMMUNITY','图谱社区'],['KG_EVIDENCE','图谱证据'],['RAPTOR_NODE','RAPTOR 树']]
const payload=()=>({documentId:props.documentId,parseTaskId:snapshot.data.value?.parseTaskId,indexTaskId:snapshot.data.value?.indexTaskId})
async function init(){
  let owner=++navigationEpoch
  const saved=context()
  await snapshot.read({documentId:props.documentId,parseTaskId:typeof route.query.parseTaskId==='string'?route.query.parseTaskId:undefined,indexTaskId:typeof route.query.indexTaskId==='string'?route.query.indexTaskId:undefined})
  if(!alive||owner!==navigationEpoch||snapshot.error.value)return
  await loadNodes()
  if(!alive||owner!==navigationEpoch)return
  if(saved.node){if(!await select(saved.node,false,saved))return;owner=navigationEpoch}
  if(graphView.value)await readGraph()
  if(alive&&owner===navigationEpoch)restoreScroll()
}
function loadNodes(){if(!payload().parseTaskId||!payload().indexTaskId)return Promise.resolve();return nodes.read({...payload(),nodeType:mode.value,keyword:appliedKeyword.value,pageNo:page.value,pageSize:'20',...(mode.value==='RAPTOR_NODE'?{rootOnly:!level.value,level:level.value||undefined}:{}),...(mode.value==='KG_ENTITY'?{entityType:entityType.value||undefined}:{})})}
function readNodes(next=page.value){navigationEpoch++;page.value=next;selected.value=null;trail.value=[];detail.data.value=null;incoming.data.value=null;outgoing.data.value=null;children.data.value=null;table.data.value=null;evidence.data.value=null;loadNodes();if(mode.value==='KG_ENTITY')readCommunities(1)}
function context(){return {node:selected.value,mode:mode.value,page:page.value,keyword:keyword.value,appliedKeyword:appliedKeyword.value,entityType:entityType.value,level:level.value,rowPage:rowPage.value,columnOffset:columnOffset.value,childPage:childPage.value,incomingPage:incomingPage.value,outgoingPage:outgoingPage.value,evidencePage:evidencePage.value,scrollY:window.scrollY}}

function search(){appliedKeyword.value=keyword.value.trim();readNodes(1)}
function readRelation(direction,pageNo=1){const state=direction==='INCOMING'?incoming:outgoing;if(direction==='INCOMING')incomingPage.value=pageNo;else outgoingPage.value=pageNo;return state.read({...payload(),nodeId:selected.value.nodeId,direction:selected.value.nodeType?.startsWith('KG_')?direction:direction==='INCOMING'?'UPSTREAM':'DOWNSTREAM',pageNo,pageSize:'10'})}
function readTable(){return table.read({...payload(),tableNodeId:selected.value.nodeId,pageNo:rowPage.value,pageSize:'20',columnOffset:columnOffset.value,columnLimit:'6'})}
function readChildren(){return children.read({...payload(),nodeType:'RAPTOR_NODE',parentNodeId:selected.value.sourceId,pageNo:childPage.value,pageSize:'20'})}
function readEvidence(next=1){evidencePage.value=next;return evidence.read({...payload(),nodeType:'KG_EVIDENCE',...(selected.value?.nodeType==='KG_RELATION'?{relationId:selected.value.sourceId}:{entityId:selected.value?.sourceId}),pageNo:next,pageSize:'5'})}
function readCommunities(next=1){communityPage.value=next;return community.read({...payload(),nodeType:'KG_COMMUNITY',pageNo:next,pageSize:'5'})}
async function select(node,remember=true,saved={}){
  if(!node?.nodeId)return false
  const owner=++navigationEpoch
  if(remember&&selected.value&&selected.value.nodeId!==node.nodeId)trail.value=[...trail.value.slice(-19),context()]
  selected.value=node;children.data.value=null;table.data.value=null;evidence.data.value=null
  rowPage.value=saved.rowPage||1;columnOffset.value=saved.columnOffset||0;childPage.value=saved.childPage||1
  const reads=[detail.read({...payload(),nodeId:node.nodeId}),readRelation('INCOMING',saved.incomingPage||1),readRelation('OUTGOING',saved.outgoingPage||1)]
  if(node.nodeType==='TABLE')reads.push(readTable())
  if(node.nodeType==='RAPTOR_NODE')reads.push(readChildren())
  if(['KG_ENTITY','KG_RELATION'].includes(node.nodeType))reads.push(readEvidence(saved.evidencePage||1))
  await Promise.all(reads);await nextTick()
  if(alive&&owner===navigationEpoch&&selected.value?.nodeId===node.nodeId){document.getElementById('doc-node-details')?.focus({preventScroll:true});if(saved.scrollY!=null)restoreScroll(saved.scrollY)}
  return alive&&owner===navigationEpoch
}
async function backTo(index){
  const saved=trail.value[index];if(!saved)return
  const owner=++navigationEpoch
  trail.value=trail.value.slice(0,index)
  mode.value=saved.mode;page.value=saved.page;keyword.value=saved.keyword;appliedKeyword.value=saved.appliedKeyword;entityType.value=saved.entityType;level.value=saved.level
  await loadNodes();if(alive&&owner===navigationEpoch)await select(saved.node,false,saved)
}
function back(){backTo(trail.value.length-1)}
async function clearSelection(){navigationEpoch++;selected.value=null;trail.value=[];await nextTick();if(alive)document.getElementById('doc-node-list')?.focus()}

function readGraph(){if(!payload().parseTaskId||!payload().indexTaskId)return;graphView.value=true;return graph.read({...payload(),maxNodes:graphLimit.value,maxEdges:'160',includeIsolates:true})}
const graphNodes=computed(()=>(graph.data.value?.nodes||[]).map((node,i,all)=>({...node,x:300+Math.cos(i*2*Math.PI/Math.max(1,all.length))*230,y:240+Math.sin(i*2*Math.PI/Math.max(1,all.length))*175})))
const positions=computed(()=>new Map(graphNodes.value.map(node=>[node.nodeId,node])))
function graphSelect(node){if(selected.value)trail.value=[...trail.value.slice(-19),context()];mode.value='KG_ENTITY';page.value=1;nodes.read({...payload(),nodeType:'KG_ENTITY',pageNo:'1',pageSize:'20'});readCommunities(1);select({...node,nodeType:'KG_ENTITY',sourceId:node.sourceId},false)}
function cell(row,column){return row.cells?.find(cell=>String(cell.columnId)===String(column.columnId))?.cellText ?? '—'}
onMounted(init)
</script>
<template><section class="admin-next-doc-panel"><h2>产物与关系</h2><ReadState :state="snapshot" label="产物快照" @retry="init" /><p v-if="snapshot.data.value&&(!payload().parseTaskId||!payload().indexTaskId)" role="status">尚无完整的解析与索引产物。</p><form class="admin-next-doc-toolbar" @submit.prevent="search"><label for="artifact-node-type" class="chat-next-sr-only">节点类型</label><select id="artifact-node-type" v-model="mode" @change="readNodes(1)"><option v-for="[value,label] in modes" :key="value" :value="value">{{ label }}</option></select><label for="artifact-node-search" class="chat-next-sr-only">搜索节点</label><Input id="artifact-node-search" v-model:value="keyword" placeholder="搜索节点" /><label v-if="mode==='KG_ENTITY'" for="artifact-entity-type">实体类型</label><Input v-if="mode==='KG_ENTITY'" id="artifact-entity-type" v-model:value="entityType" /><label v-if="mode==='RAPTOR_NODE'" for="artifact-level">层级</label><input v-if="mode==='RAPTOR_NODE'" id="artifact-level" v-model="level" type="number" min="0" /><Button html-type="submit">搜索节点</Button><Button @click="readGraph">图谱窗口</Button></form><ReadState :state="nodes" label="节点" @retry="readNodes()" />
<section v-if="graphView" class="admin-next-doc-subpanel"><div class="admin-next-doc-toolbar"><label for="graph-limit">节点上限</label><select id="graph-limit" v-model="graphLimit"><option value="40">40</option><option value="80">80</option><option value="120">120</option></select><Button @click="readGraph">刷新图谱</Button><Button @click="zoom=Math.min(3,zoom+.25)">放大</Button><Button @click="zoom=Math.max(.5,zoom-.25)">缩小</Button><Button @click="zoom=1">适应画布</Button><Button @click="graphView=false">收起图谱</Button></div><ReadState :state="graph" label="图谱窗口" @retry="readGraph" /><Facts v-if="graph.data.value" :value="graph.data.value.stats" :labels="{totalEntities:'实体总量',connectedEntities:'有连接实体',isolatedEntities:'孤立实体',totalRelations:'关系总量',returnedNodes:'窗口节点',returnedEdges:'窗口边',truncated:'窗口已截断'}" /><div v-if="graph.data.value?.nodes?.length" class="admin-next-doc-scroll" role="region" aria-label="图谱画布" tabindex="0"><svg :width="600*zoom" :height="480*zoom" viewBox="0 0 600 480" role="img" aria-label="当前图谱窗口，节点和关系可在下方列表访问"><line v-for="edge in ((graph.data.value.edges || []).filter(edge=>positions.has(edge.sourceNodeId)&amp;&amp;positions.has(edge.targetNodeId)))" :key="edge.edgeId" :x1="positions.get(edge.sourceNodeId)?.x" :y1="positions.get(edge.sourceNodeId)?.y" :x2="positions.get(edge.targetNodeId)?.x" :y2="positions.get(edge.targetNodeId)?.y" class="admin-next-doc-edge" /><g v-for="node in graphNodes" :key="node.nodeId"><circle :cx="node.x" :cy="node.y" r="9" class="admin-next-doc-node" /><text :x="node.x" :y="node.y+23" text-anchor="middle">{{ String(node.label||'').slice(0,10) }}</text></g></svg></div><div class="admin-next-doc-toolbar"><Button v-for="node in graphNodes" :key="node.nodeId" @click="graphSelect(node)">{{ node.label || node.nodeId }}</Button></div><details v-if="graph.data.value"><summary>图谱关系列表</summary><Facts :value="graph.data.value.edges" /></details><Empty v-if="graph.data.value&&!graph.data.value.nodes?.length" description="暂无图谱节点" /></section>
<div class="admin-next-doc-columns admin-next-doc-explorer"><div><h3 id="doc-node-list" tabindex="-1">节点列表</h3><ul class="admin-next-doc-items"><li v-for="node in nodes.data.value?.records||[]" :key="node.nodeId"><Button type="link" :aria-pressed="selected?.nodeId===node.nodeId" @click="select(node)">{{ node.label || node.nodeId }}</Button><span class="admin-next-doc-muted">{{ node.sectionPath }} {{ node.pageRange }}</span></li></ul><Empty v-if="nodes.data.value&&!nodes.data.value.records?.length" description="暂无此类节点" /><nav v-if="nodes.data.value" class="admin-next-doc-toolbar" aria-label="节点分页"><Button :disabled="page<=1||nodes.loading.value" @click="readNodes(page-1)">上一页节点</Button><span>{{ page }} 页 · 共 {{ nodes.data.value.total ?? '—' }}</span><Button :disabled="page*20>=Number(nodes.data.value.total)||nodes.loading.value" @click="readNodes(page+1)">下一页节点</Button></nav><section v-if="mode==='KG_ENTITY'"><h3>图谱社区</h3><ReadState :state="community" label="社区" @retry="readCommunities(communityPage)" /><Button v-for="node in community.data.value?.records||[]" :key="node.nodeId" @click="select(node)">{{ node.label }}</Button><div class="admin-next-doc-toolbar"><Button :disabled="communityPage<=1" @click="readCommunities(communityPage-1)">上一页社区</Button><Button :disabled="communityPage*5>=Number(community.data.value?.total)" @click="readCommunities(communityPage+1)">下一页社区</Button></div></section></div>
<section v-if="selected" aria-label="选中节点"><nav class="admin-next-doc-breadcrumb" aria-label="节点浏览路径"><Button @click="clearSelection">返回节点列表</Button><template v-for="(entry,index) in trail" :key="index"><span aria-hidden="true">/</span><Button type="link" @click="backTo(index)">{{ entry.node.label || entry.node.nodeId }}</Button></template><span aria-hidden="true">/</span><span>{{ selected.label || selected.nodeId }}</span></nav><div class="admin-next-doc-toolbar"><Button v-if="trail.length" @click="back">返回上一节点</Button><h3 id="doc-node-details" tabindex="-1">{{ selected.label || selected.nodeId }}</h3><Button v-if="selected.pageNo!=null" @click="$emit('locate',selected)">定位原页</Button></div><ReadState :state="detail" label="节点详情" @retry="select(selected,false)" /><template v-if="detail.data.value"><p class="admin-next-doc-id">{{ selected.nodeId }}</p><p class="admin-next-doc-content">{{ detail.data.value.content }}</p><Facts :value="detail.data.value.attributes" /><Facts :value="detail.data.value.presentation" /><details><summary>节点元数据</summary><Facts :value="detail.data.value.node" /></details></template>
<section v-for="[direction,state,current] in [['INCOMING',incoming,incomingPage],['OUTGOING',outgoing,outgoingPage]]" :key="direction"><h3>{{ direction==='INCOMING'?'上游 / 入边':'下游 / 出边' }}</h3><ReadState :state="state" label="关系" @retry="readRelation(direction,current)" /><ul class="admin-next-doc-items"><li v-for="(item,i) in state.data.value?.records||[]" :key="item.edge?.edgeId||i"><Button @click="select(item.node)">{{ item.node?.label || item.node?.nodeId }}</Button><span>{{ item.edge?.label }} {{ item.edge?.detail }}</span></li></ul><div v-if="state.data.value" class="admin-next-doc-toolbar"><Button :disabled="current<=1||state.loading.value" @click="readRelation(direction,current-1)">上一页关系</Button><span>{{ current }} 页 · 共 {{ state.data.value.total ?? '—' }}</span><Button :disabled="current*10>=Number(state.data.value.total)||state.loading.value" @click="readRelation(direction,current+1)">下一页关系</Button></div></section>
<section v-if="selected.nodeType==='RAPTOR_NODE'"><h3>子节点</h3><ReadState :state="children" label="子节点" @retry="readChildren" /><ul class="admin-next-doc-items"><li v-for="node in children.data.value?.records || []" :key="node.nodeId"><Button @click="select(node)">{{ node.label || node.nodeId }}</Button></li></ul><p v-if="children.data.value&&!children.data.value.records?.length">没有下级节点</p><div class="admin-next-doc-toolbar"><Button :disabled="childPage<=1" @click="childPage--;readChildren()">上一页子节点</Button><Button :disabled="childPage*20>=Number(children.data.value?.total)" @click="childPage++;readChildren()">下一页子节点</Button></div></section>
<section v-if="['KG_ENTITY','KG_RELATION'].includes(selected.nodeType)"><h3>图谱证据</h3><ReadState :state="evidence" label="图谱证据" @retry="readEvidence(evidencePage)" /><ul class="admin-next-doc-items"><li v-for="node in evidence.data.value?.records||[]" :key="node.nodeId"><Button @click="select(node)">{{ node.label || node.nodeId }}</Button><span>{{ node.textPreview }}</span></li></ul><div class="admin-next-doc-toolbar"><Button :disabled="evidencePage<=1" @click="readEvidence(evidencePage-1)">上一页证据</Button><Button :disabled="evidencePage*5>=Number(evidence.data.value?.total)" @click="readEvidence(evidencePage+1)">下一页证据</Button></div></section>
<section v-if="selected.nodeType==='TABLE'"><h3>表格窗口</h3><ReadState :state="table" label="表格窗口" @retry="readTable" /><div v-if="table.data.value" class="admin-next-doc-scroll" role="region" aria-label="表格窗口" tabindex="0"><table><thead><tr><th v-for="col in table.data.value.columns||[]" :key="col.columnId" scope="col">{{ col.columnName }}</th></tr></thead><tbody><tr v-for="row in table.data.value.records||[]" :key="row.rowId"><td v-for="col in table.data.value.columns||[]" :key="col.columnId">{{ cell(row,col) }}</td></tr></tbody></table></div><p v-if="table.data.value" class="admin-next-doc-muted">{{ table.data.value.totalRows }} 行 × {{ table.data.value.totalColumns }} 列</p><div class="admin-next-doc-toolbar"><Button :disabled="rowPage<=1||table.loading.value" @click="rowPage--;readTable()">上一页表格行</Button><Button :disabled="rowPage*20>=Number(table.data.value?.totalRows)||table.loading.value" @click="rowPage++;readTable()">下一页表格行</Button><Button :disabled="columnOffset<=0||table.loading.value" @click="columnOffset=Math.max(0,columnOffset-6);readTable()">前六列</Button><Button :disabled="columnOffset+6>=Number(table.data.value?.totalColumns)||table.loading.value" @click="columnOffset+=6;readTable()">后六列</Button></div></section>
</section></div></section></template>
